def compute(vars):
    old_sales = vars["v1"]
    new_sales = vars["v2"]

    if old_sales == 0:
        return None

    change_ratio = (new_sales - old_sales) / old_sales
    growth_rate_percent = change_ratio * 100

    return {
        "value": growth_rate_percent,
        "trace": {
            "old_sales": old_sales,
            "new_sales": new_sales,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
